-- Somente no PostgreSQL isolado: nenhum dado real.
\set ON_ERROR_STOP on
do $$begin if to_regclass('public.test_rights') is null then raise exception 'SOMENTE NO LABORATORIO ISOLADO'; end if;end$$;
truncate esc_save_private.accounts,esc_save_private.careers,esc_save_private.versions,esc_save_private.requests,public.esc_pyramid_saves,public.esc_salvar_teste,public.esc_saves_lixeira,public.esc_carreiras_barradas cascade;
update esc_save_private.policy set cleanup_after=now()+interval '7 days';
update public.test_rights set rights='{"pago":true,"tier":"prata"}' where email='pago@test.invalid';
create or replace function public.test_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is not true then raise exception 'FALHOU: %',label; end if;end$$;
insert into esc_pyramid_saves(user_id,save,updated_at) values('00000000-0000-4000-a000-000000000001','{"__multi":1,"careers":[{"save":{"seed":91,"careerOnline":true,"onlineMode":"cpu","managers":[{"teamName":"Clube de teste"}],"seasonNo":4,"round":30},"at":1000}]}',now());
-- Save de conta grátis feito na regra antiga continua acessível.
insert into esc_pyramid_saves(user_id,save,updated_at) values('00000000-0000-4000-a000-000000000002','{"seed":93,"careerOnline":true,"onlineMode":"cpu","managers":[{}],"round":9}',now());
insert into esc_salvar_teste(uid,inicio) values('00000000-0000-4000-a000-000000000002',now()-interval '6 days');
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000001',false);
select set_config('request.jwt.claim.role','authenticated',false);
select public.test_assert((esc_carreiras_manifesto_v2(auth.uid())->'careers'->0->>'revision')::int=1,'importação legada');
select public.test_assert((esc_carreiras_manifesto_v2(auth.uid())->>'save') is null,'manifesto sem payload');
select public.test_assert((esc_carreira_salvar_v2(auth.uid(),91,'{"seed":91,"careerOnline":true,"onlineMode":"cpu","managers":[{"teamName":"Clube de teste"}],"seasonNo":4,"round":31}',1,'00000000-0000-0000-0000-000000000101')->>'status')='saved','salvar CAS');
select public.test_assert((esc_carreira_salvar_v2(auth.uid(),91,'{"seed":91,"careerOnline":true,"onlineMode":"cpu","managers":[{}],"seasonNo":4,"round":1}',1,'00000000-0000-0000-0000-000000000102')->>'status')='conflict','aba antiga não apaga rodada');
select public.test_assert((esc_carreira_salvar_v2(auth.uid(),91,'{}',1,'00000000-0000-0000-0000-000000000101')->'summary'->>'revision')::int=2,'repetir pedido não repete gravação');
select public.test_assert((esc_carreira_ler_v2(auth.uid(),91)->'save'->>'round')::int=31,'rodada atual preservada');
do $$begin update public.esc_pyramid_saves set save='{}';raise exception 'FALHOU: cliente legado gravou';exception when serialization_failure then null;end$$;
select public.test_assert((esc_carreira_salvar_v2(auth.uid(),91,null,2,'00000000-0000-0000-0000-000000000103',1)->'summary'->>'revision')::int=3,'restaurar vira nova revisão');
select public.test_assert((esc_carreira_ler_v2(auth.uid(),91)->'save'->>'round')::int=30,'anterior recuperado');
select public.test_assert((esc_carreira_historico_v2(auth.uid(),91)->0->>'revision')::int=2,'restaurar preserva ponto atual');
select public.test_assert((esc_carreira_excluir_v2(auth.uid(),91,2,'00000000-0000-0000-0000-000000000104')->>'status')='conflict','exclusão stale bloqueada');
select public.test_assert((esc_carreira_excluir_v2(auth.uid(),91,3,'00000000-0000-0000-0000-000000000105')->>'status')='deleted','exclusão CAS');
select public.test_assert(jsonb_array_length(esc_carreiras_manifesto_v2(auth.uid())->'careers')=0,'legado não ressuscita excluída');
select public.test_assert((esc_carreira_salvar_v2(auth.uid(),91,'{}',3,'00000000-0000-0000-0000-000000000106')->>'status')='deleted','aba aberta não ressuscita excluída');
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000002',false);
do $$begin update public.esc_pyramid_saves set save=save where user_id=auth.uid(); raise exception 'FALHOU: cliente antigo grátis enviou nuvem'; exception when insufficient_privilege then null; end$$;
select public.test_assert((esc_carreira_ler_v2(auth.uid(),91)->>'status')='missing','leitura isolada por conta');
do $$begin perform public.esc_carreiras_manifesto_v2('00000000-0000-4000-a000-000000000001'); raise exception 'FALHOU: conta trocada aceita'; exception when insufficient_privilege then null; end$$;
select public.test_assert((esc_carreira_salvar_v2(auth.uid(),92,'{"seed":92,"careerOnline":true,"onlineMode":"cpu","oficial":{},"managers":[{}]}',0,'00000000-0000-0000-0000-000000000107')->>'status')='local_only','grátis oficial só aparelho');
select public.test_assert((esc_carreira_salvar_v2(auth.uid(),93,'{"seed":93,"careerOnline":true,"onlineMode":"cpu","managers":[{}]}',1,'00000000-0000-0000-0000-000000000108')->>'status')='local_only','conta grátis tradicional só aparelho');
select public.test_assert((esc_carreira_salvar_v2(auth.uid(),94,'{"seed":94,"careerOnline":true,"onlineMode":"cpu","managers":[{}]}',0,'00000000-0000-0000-0000-000000000109')->>'status')='local_only','carreira nova tradicional grátis não sobe');
reset role;
update esc_salvar_teste set inicio=now()-interval '6 days' where uid='00000000-0000-4000-a000-000000000002';
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000002',false);
select public.test_assert((esc_carreira_salvar_v2(auth.uid(),93,'{"seed":93,"careerOnline":true,"onlineMode":"cpu","managers":[{}],"round":2}',1,'00000000-0000-0000-0000-000000000110')->>'status')='local_only','teste antigo vencido não controla a regra nova');
select public.test_assert((esc_carreira_ler_v2(auth.uid(),93)->>'status')='ok','save antigo da nuvem permanece legível');
select public.test_assert((esc_carreira_ler_v2(auth.uid(),93)->'save'->>'round')::int=9,'tentativa grátis não alterou a nuvem antiga');
select public.test_assert(not has_function_privilege('authenticated','public.esc_nuvem_gratis_limpa()','execute'),'limpeza obsoleta protegida');
select public.test_assert(not has_table_privilege('authenticated','esc_save_private.careers','update'),'sem escrita bruta');
select set_config('request.jwt.claim.sub','',false);
do $$begin perform public.esc_carreiras_manifesto_v2(auth.uid());raise exception 'FALHOU: sem conta salvou';exception when insufficient_privilege then null;end$$;
reset role;
select public.test_assert(esc_save_private.maintenance()->>'status'='grace','conservação não apaga na implantação');
select public.test_assert(exists(select 1 from public.esc_pyramid_saves where user_id='00000000-0000-4000-a000-000000000001'),'origem legada preservada na transição');
select 'OK: protocolo, conflitos, direitos, idempotência, recuperação e isolamento' as resultado;
